    #[test]
    fn on_input_disabled_short_circuits() {
        let (mut c, engine) = fixture();
        // enabled stays false.
        let trace = Arc::new(Mutex::new(Vec::new()));
        c.lanes.push(Box::new(
            TestLane::new("a", LanePhase::Decide, trace.clone()).with_filter(InputFilter::All),
