                            }
                        });
                    // Per-voice harmony overrides — all optional.
                    voice.voice_count = item
                        .get("voice_count")
                        .and_then(|v| v.as_u64())
                        .map(|n| (n as u8).clamp(1, 4));
                    voice.voice_position = item
                        .get("voice_position")
                        .and_then(|v| v.as_u64())
                        .map(|n| (n as u8).min(3));
                    voice.voice_leading_enabled =
