                    voice.voice_leading_style = item
                        .get("voice_leading_style")
                        .and_then(|v| v.as_str())
                        .and_then(voice_leading_style_from_str);
                    voice.octave_mode = item
                        .get("octave_mode")
                        .and_then(|v| v.as_str())
