        let notes: Vec<u8> = out
            .ops
            .iter()
            .filter_map(|op| match op {
                DispatchOp::NoteOn { note, .. } => Some(*note),
                _ => None,
            })
            .collect();
        // C major triad notes: C(60), E(64), G(67).
        assert!(notes.contains(&60), "should include unison C: {:?}", notes);
        assert!(
